function validate([rooks]) {
  const n = rooks.length;
  if (n < 1 || n > 500) return 'rooks needs 1 to 500 rooks.';
  const seen = new Set();
  for (const rook of rooks) {
    if (rook.length !== 2) return 'Each rook is a pair [x, y].';
    const [x, y] = rook;
    if (x < 0 || y < 0 || x >= n || y >= n) return 'Each coordinate is between 0 and n - 1, where n is the number of rooks.';
    if (seen.has(x * n + y)) return 'Two rooks cannot start on the same cell.';
    seen.add(x * n + y);
  }
  return null;
}

