function minMoves(rooks) {
  const rows = rooks.map(rook => rook[0]).sort((a, b) => a - b);
  const cols = rooks.map(rook => rook[1]).sort((a, b) => a - b);
  let moves = 0;
  for (let i = 0; i < rooks.length; i++) {
    moves += Math.abs(rows[i] - i);
    moves += Math.abs(cols[i] - i);
  }
  return moves;
}

