function minMoves(rooks) {
  const n = rooks.length;
  if (n <= 4) {
    // Small boards: breadth-first search over real positions; a move slides one rook into an empty neighbouring cell.
    const start = rooks.reduce((mask, [x, y]) => mask | 1 << (x * n + y), 0);
    const peaceful = mask => {
      for (let line = 0; line < n; line++) {
        let inRow = 0, inColumn = 0;
        for (let k = 0; k < n; k++) {
          if (mask >> (line * n + k) & 1) inRow++;
          if (mask >> (k * n + line) & 1) inColumn++;
        }
        if (inRow !== 1 || inColumn !== 1) return false;
      }
      return true;
    };
    const distance = new Map([[start, 0]]);
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const mask = queue[head];
      if (peaceful(mask)) return distance.get(mask);
      for (let cell = 0; cell < n * n; cell++) {
        if (!(mask >> cell & 1)) continue;
        const x = Math.floor(cell / n), y = cell % n;
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nx = x + dx, ny = y + dy;
          if (nx < 0 || ny < 0 || nx >= n || ny >= n || mask >> (nx * n + ny) & 1) continue;
          const next = mask & ~(1 << cell) | 1 << (nx * n + ny);
          if (!distance.has(next)) {
            distance.set(next, distance.get(mask) + 1);
            queue.push(next);
          }
        }
      }
    }
  }
  // Larger boards: rows and columns are fixed separately, so try every assignment of rooks to distinct lines (subset DP).
  const cheapest = coords => {
    const best = new Array(1 << n).fill(Infinity);
    best[0] = 0;
    for (let mask = 0; mask < 1 << n; mask++) {
      let placed = 0;
      for (let bit = 0; bit < n; bit++) if (mask >> bit & 1) placed++;
      for (let line = 0; line < n; line++) {
        if (mask >> line & 1) continue;
        const next = mask | 1 << line;
        best[next] = Math.min(best[next], best[mask] + Math.abs(coords[placed] - line));
      }
    }
    return best[(1 << n) - 1];
  };
  return cheapest(rooks.map(rook => rook[0])) + cheapest(rooks.map(rook => rook[1]));
}

