function generate(rand, size) {
  const n = size === 'large' ? 500 : rand() < 0.7 ? 1 + Math.floor(rand() * 4) : 5 + Math.floor(rand() * 3);
  const randomInt = limit => Math.floor(rand() * limit);
  const shuffled = () => {
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) {
      const j = randomInt(i + 1);
      [order[i], order[j]] = [order[j], order[i]];
    }
    return order;
  };
  const rooks = [];
  const taken = new Set();
  const place = (x, y) => {
    if (taken.has(x * n + y)) return;
    taken.add(x * n + y);
    rooks.push([x, y]);
  };
  const mode = randomInt(5);
  if (mode === 0) {
    // Anywhere on the board.
    while (rooks.length < n) place(randomInt(n), randomInt(n));
  } else if (mode === 1) {
    // All in one row or all in one column.
    const line = randomInt(n);
    const inRow = rand() < 0.5;
    for (const k of shuffled()) {
      if (inRow) place(line, k);
      else place(k, line);
    }
  } else if (mode === 2) {
    // Packed into a small block in the corner.
    const side = Math.ceil(Math.sqrt(n));
    while (rooks.length < n) place(randomInt(side), randomInt(side));
  } else {
    // A peaceful board, then (in mode 4) a few single-step nudges.
    shuffled().forEach((y, x) => place(x, y));
    const nudges = mode === 4 ? 1 + randomInt(Math.min(n, 30)) : 0;
    for (let t = 0; t < nudges; t++) {
      const index = randomInt(n);
      const [x, y] = rooks[index];
      const [dx, dy] = [[1, 0], [-1, 0], [0, 1], [0, -1]][randomInt(4)];
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= n || ny >= n || taken.has(nx * n + ny)) continue;
      taken.delete(x * n + y);
      taken.add(nx * n + ny);
      rooks[index] = [nx, ny];
    }
  }
  return [rooks];
}
